#[derive(Debug)]
struct PinnedCertVerifier {
    inner: Arc<dyn rustls::client::danger::ServerCertVerifier>,
    pins: Vec<[u8; 32]>,
}

impl rustls::client::danger::ServerCertVerifier for PinnedCertVerifier {
    fn verify_server_cert(
        &self,
        end_entity: &rustls::pki_types::CertificateDer<'_>,
        intermediates: &[rustls::pki_types::CertificateDer<'_>],
        server_name: &rustls::pki_types::ServerName<'_>,
        ocsp_response: &[u8],
        now: rustls::pki_types::UnixTime,
    ) -> std::result::Result<rustls::client::danger::ServerCertVerified, rustls::Error> {
        self.inner.verify_server_cert(
            end_entity,
            intermediates,
            server_name,
            ocsp_response,
            now,
        )?;
        let mut hasher = Sha256::new();
        hasher.update(end_entity.as_ref());
        let actual: [u8; 32] = hasher.finalize().into();
        if self.pins.iter().any(|p| p == &actual) {
            Ok(rustls::client::danger::ServerCertVerified::assertion())
        } else {
            Err(rustls::Error::General(
                "E_TLS: server certificate hash mismatch".to_string(),
            ))
        }
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &rustls::pki_types::CertificateDer<'_>,
        dss: &rustls::DigitallySignedStruct,
    ) -> std::result::Result<rustls::client::danger::HandshakeSignatureValid, rustls::Error> {
        self.inner.verify_tls12_signature(message, cert, dss)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &rustls::pki_types::CertificateDer<'_>,
        dss: &rustls::DigitallySignedStruct,
    ) -> std::result::Result<rustls::client::danger::HandshakeSignatureValid, rustls::Error> {
        self.inner.verify_tls13_signature(message, cert, dss)
    }

    fn supported_verify_schemes(&self) -> Vec<rustls::SignatureScheme> {
        self.inner.supported_verify_schemes()
    }
}

fn parse_server_certificate_hashes(
    opts: &serde_json::Value,
) -> std::result::Result<Vec<[u8; 32]>, String> {
    let mut out = Vec::new();
    let Some(arr) = opts
        .get("serverCertificateHashes")
        .and_then(|v| v.as_array())
    else {
        return Ok(out);
    };
    for entry in arr {
        let algorithm = entry
            .get("algorithm")
            .and_then(|v| v.as_str())
            .unwrap_or_default();
        if algorithm != "sha-256" {
            return Err(format!(
                "E_INTERNAL: serverCertificateHashes only supports algorithm \"sha-256\", got \"{}\"",
                algorithm
            ));
        }
        let value_b64 = entry
            .get("valueBase64")
            .and_then(|v| v.as_str())
            .ok_or_else(|| {
                "E_INTERNAL: serverCertificateHashes entry value must be base64".to_string()
            })?;
        let decoded = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, value_b64)
            .map_err(|_| "E_INTERNAL: invalid base64 in serverCertificateHashes".to_string())?;
        if decoded.len() != 32 {
            return Err(
                "E_INTERNAL: serverCertificateHashes value must be 32-byte SHA-256".to_string(),
            );
        }
        let mut pin = [0u8; 32];
        pin.copy_from_slice(&decoded);
        out.push(pin);
    }
    Ok(out)
}

/// Result of run_connect: session id, peer info, connection, and optional pool release guard.
pub type RunConnectResult = (
    String,
    String,
    u32,
    wtransport::Connection,
    Option<PoolReleaseGuard>,
);

async fn run_connect(
    url: &str,
    opts_json: String,
) -> std::result::Result<RunConnectResult, Box<dyn std::error::Error + Send + Sync>> {
    let opts = serde_json::from_str::<serde_json::Value>(&opts_json).unwrap_or_default();

    let tls_opts = opts.get("tls");
    let insecure_skip_verify = tls_opts
        .and_then(|t| t.get("insecureSkipVerify")?.as_bool())
        .unwrap_or(false);

    let ca_pem = tls_opts
        .and_then(|t| t.get("caPem")?.as_str())
        .filter(|s| !s.is_empty());

    let server_name = tls_opts
        .and_then(|t| t.get("serverName")?.as_str())
        .filter(|s| !s.is_empty());
    let pinned_hashes = parse_server_certificate_hashes(&opts).map_err(std::io::Error::other)?;

    let allow_pooling = opts
        .get("allowPooling")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let require_unreliable = opts
        .get("requireUnreliable")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if allow_pooling && !pinned_hashes.is_empty() {
        return Err(
            "E_INTERNAL: serverCertificateHashes cannot be used with allowPooling=true".into(),
        );
    }

    let handshake_timeout_ms = opts
        .get("limits")
        .and_then(|l| l.get("handshakeTimeoutMs")?.as_u64())
        .unwrap_or(DEFAULT_HANDSHAKE_TIMEOUT_MS);

    let (connect_url, custom_resolver) =
        connect_url_and_resolver(url, server_name).map_err(std::io::Error::other)?;

    let id = format!(
        "client-{}",
        CLIENT_SESSION_ID_COUNTER.fetch_add(1, Ordering::Relaxed)
    );

    if allow_pooling {
        let parsed = url::Url::parse(url).map_err(|e| format!("E_TLS: invalid URL: {}", e))?;
        let pool_key = PoolKey {
            scheme: parsed.scheme().to_string(),
            host: parsed.host_str().unwrap_or("").to_string(),
            port: parsed.port().unwrap_or(443),
            sni: server_name.map(String::from),
            insecure_skip_verify,
            has_pinned_hashes: !pinned_hashes.is_empty(),
            has_ca_pem: ca_pem.is_some(),
            require_unreliable,
            congestion: opts
                .get("congestionControl")
                .and_then(|v| v.as_str())
                .unwrap_or("default")
                .to_string(),
        };
        let ca_pem_owned = ca_pem.map(String::from);
        let pinned_hashes_clone = pinned_hashes.clone();
        let create_endpoint = move || {
            let mut config = if insecure_skip_verify {
                wtransport::ClientConfig::builder()
                    .with_bind_default()
                    .with_no_cert_validation()
                    .build()
            } else if ca_pem_owned.is_some() || !pinned_hashes_clone.is_empty() {
                let root_store = build_root_cert_store(ca_pem_owned.as_deref())
                    .map_err(std::io::Error::other)?;
                let tls_config =
                    build_client_tls_config(root_store, false, pinned_hashes_clone.as_slice());
                wtransport::ClientConfig::builder()
                    .with_bind_default()
                    .with_custom_tls(tls_config)
                    .build()
            } else {
                wtransport::ClientConfig::builder()
                    .with_bind_default()
                    .with_native_certs()
                    .build()
            };
            if let Some(resolver) = custom_resolver {
                config.set_dns_resolver(resolver);
            }
            wtransport::Endpoint::client(config).map_err(|e| e.into())
        };

        let (conn, release_guard, _was_hit) = CLIENT_POOL
            .acquire_connect(
                pool_key,
                &connect_url,
                handshake_timeout_ms,
                create_endpoint,
            )
            .await?;

        let addr = conn.remote_address();
        let peer_ip = addr.ip().to_string();
        let peer_port = addr.port() as u32;
        return Ok((id, peer_ip, peer_port, conn, Some(release_guard)));
    }

    let mut config = if insecure_skip_verify {
        wtransport::ClientConfig::builder()
            .with_bind_default()
            .with_no_cert_validation()
            .build()
    } else if ca_pem.is_some() || !pinned_hashes.is_empty() {
        let root_store = build_root_cert_store(ca_pem).map_err(std::io::Error::other)?;
        let tls_config = build_client_tls_config(root_store, false, pinned_hashes.as_slice());
        wtransport::ClientConfig::builder()
            .with_bind_default()
            .with_custom_tls(tls_config)
            .build()
    } else {
        wtransport::ClientConfig::builder()
            .with_bind_default()
            .with_native_certs()
            .build()
    };

    if let Some(resolver) = custom_resolver {
        config.set_dns_resolver(resolver);
    }

    let endpoint = wtransport::Endpoint::client(config)?;
    let conn = tokio::time::timeout(
        tokio::time::Duration::from_millis(handshake_timeout_ms),
        endpoint.connect(&connect_url),
    )
    .await
    .map_err(|_| "E_HANDSHAKE_TIMEOUT")??;

    let addr = conn.remote_address();
    let peer_ip = addr.ip().to_string();
    let peer_port = addr.port() as u32;

    Ok((id, peer_ip, peer_port, conn, None))
}

